import{_ as l,C as t,o as p,c as d,a2 as n,j as s,G as r,a as c}from"./chunks/framework.BgSoyxN5.js";const C=JSON.parse('{"title":"Идеи по акциям | Девять скринов, которые сами выбирают компании | TickerForge","description":"Девять регулярных форматов идей: у каждого фиксированное правило, карточка, собранная из данных, и компания, выбранная скрином, а не редактором. Что каждый формат ищет, чего намеренно не проверяет и как канал это публикует.","frontmatter":{"title":"Идеи по акциям | Девять скринов, которые сами выбирают компании | TickerForge","description":"Девять регулярных форматов идей: у каждого фиксированное правило, карточка, собранная из данных, и компания, выбранная скрином, а не редактором. Что каждый формат ищет, чего намеренно не проверяет и как канал это публикует.","aside":false,"locale":"ru","alternateLocales":{"en":"/stock-ideas","ru":"/ru/stock-ideas"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/stock-ideas.md","filePath":"ru/stock-ideas.md","lastUpdated":1788411072000}'),m={name:"ru/stock-ideas.md"},g={class:"partners-wide"},h={class:"partners-post-gallery"},v={class:"partners-wide"};function _(b,a,f,k,u,P){const e=t("PartnerPostImage"),i=t("PartnerCabinetCta"),o=t("PartnerLeadForm");return p(),d("div",null,[a[0]||(a[0]=n('<h1 id="идеи-по-акциям" tabindex="-1">Идеи по акциям <a class="header-anchor" href="#идеи-по-акциям" aria-label="Permalink to &quot;Идеи по акциям&quot;">​</a></h1><p>Девять регулярных форматов. У каждого фиксированное правило, каждый сам выбирает компанию из одного и того же дневного среза и печатает карточку, собранную из цифр этой компании.</p><p>Дело не в том, что список длинный. Дело в том, что каждую идею в нём можно проверить: правило записано, цифры на карточке — те самые, которые читало правило, и на следующей неделе тот же скрин отработает снова, независимо от того, сработала ли идея прошлой недели.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/stockdiscovery">Прогнать скрины самому</a><a class="partners-button partners-button--secondary" href="/ru/partners/stock-analysis-and-ideas">Публиковать это в своём канале</a></div><p class="partners-locale-switch"><a href="/stock-ideas" hreflang="en">Read this page in English</a></p><p>TickerForge — образовательное программное обеспечение для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="чем-это-отличается-от-подборки" tabindex="-1">Чем это отличается от подборки <a class="header-anchor" href="#чем-это-отличается-от-подборки" aria-label="Permalink to &quot;Чем это отличается от подборки&quot;">​</a></h2><p>У большинства лент с идеями одна общая черта: непонятно, почему имя попало в список, — а значит, непонятно, когда его оттуда убирать.</p><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>Правило фиксировано</span><strong>Записано до того, как выбрана компания.</strong><p>Каждый формат заранее объявляет свой порог: оценка выше значения, качество, которое должно удержаться, денежный поток, который должен расти. Скрин применяет правило; никто не протаскивает через него любимое имя.</p></div><div class="partners-card"><span>Карточка — это данные</span><strong>Каждая цифра на ней — та, которую читало правило.</strong><p>Картинка рисуется из того же среза, на котором отработал скрин. Это не сток-графика с подставленным тикером: если показателя нет, карточка убирает строку, а не придумывает значение.</p></div><div class="partners-card"><span>Ограничения напечатаны</span><strong>Каждый формат говорит, чего он не проверяет.</strong><p>Скрин роста не смотрит на цену. Скрин недооценки не утверждает, что дисконт незаслуженный. Написать это прямо в посте — то, что отличает исследовательский формат от наводки.</p></div></div><h2 id="как-компания-попадает-в-пост" tabindex="-1">Как компания попадает в пост <a class="header-anchor" href="#как-компания-попадает-в-пост" aria-label="Permalink to &quot;Как компания попадает в пост&quot;">​</a></h2><p>Один конвейер и девять вопросов к нему.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Шаг 1</span><strong>Один дневной срез</strong><p>Каждая покрытая компания получает датированную запись: качество бизнеса, риск, рост, контекст оценки, состав держателей, активность инсайдеров и тайминг — всё посчитано одинаково для всех.</p></div><div class="partners-format"><span>Шаг 2</span><strong>Собственный порог формата</strong><p>Каждый скрин фильтрует этот срез по своему опубликованному правилу и ранжирует то, что прошло. Ручного отбора нет, и одно и то же правило работает на сайте, в канале и в партнёрском посте.</p></div><div class="partners-format"><span>Шаг 3</span><strong>Одно имя — вместе с доказательствами</strong><p>Постом становится верхняя компания, которая не выходила недавно, а рядом на карточке печатаются те цифры, которые прочитал её порог.</p></div></div></div><p>Компания может пройти сразу несколько скринов — и это информация, а не дубль: имя, прошедшее в одну неделю и порог роста, и порог состава держателей, — это другое наблюдение, чем имя, прошедшее только один.</p><h2 id="девять-форматов" tabindex="-1">Девять форматов <a class="header-anchor" href="#девять-форматов" aria-label="Permalink to &quot;Девять форматов&quot;">​</a></h2><h3 id="восстановление-и-качество" tabindex="-1">Восстановление и качество <a class="header-anchor" href="#восстановление-и-качество" aria-label="Permalink to &quot;Восстановление и качество&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Еженедельно · в Partner Cabinet</span><strong>🔄 Разворот обнаружен</strong><p>Квартальные цифры, которые начали двигаться в обратную сторону после полосы спада. Оценка разворота читает выручку, маржинальность, денежный поток и баланс вместе — поэтому она движется медленно и может откатиться назад.</p><p class="partners-format__limit">Не утверждает, что восстановление продолжится. Многие развороты срываются.</p></div><div class="partners-format"><span>Еженедельно · в Partner Cabinet</span><strong>🏆 Тройной рейтинг</strong><p>Компания, прошедшая три фиксированных порога в один день: оценка TickerForge, F-Score Пиотроски и Z-Score Альтмана. Пороги заданы заранее и не подгонялись под то имя, которое их прошло.</p><p class="partners-format__limit">Ничего не говорит о цене. Компания может пройти все три и всё равно быть дорогой.</p></div><div class="partners-format"><span>Еженедельно · только в канале</span><strong>🩺 Стресс баланса</strong><p>Те же три порога, прочитанные наоборот: компания, проваливающая их одновременно. Публикуется как предупреждение, а не как идея для шорта.</p><p class="partners-format__limit">Стресс — это показание, а не прогноз банкротства.</p></div></div></div><h3 id="weekly-gems" tabindex="-1">Weekly Gems <a class="header-anchor" href="#weekly-gems" aria-label="Permalink to &quot;Weekly Gems&quot;">​</a></h3><p>Три скрина делят один понедельничный слот и чередуются по неделям, задавая одному и тому же срезу разные вопросы.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Еженедельно · в Partner Cabinet</span><strong>🌱 Рост в цифрах</strong><p>Выручка, прибыль и денежный поток по-прежнему движутся в нужную сторону на скользящих двенадцати месяцах — не в прогнозе, — и качество бизнеса под ними держится.</p><p class="partners-format__limit">Не проверяет цену. Компания может расти ровно так, как описано, и всё равно стоить дороже этого роста.</p></div><div class="partners-format"><span>Еженедельно · в Partner Cabinet</span><strong>💰 Дешевле своей стоимости</strong><p>Цена ниже оценки справедливой стоимости — там, где эта оценка применима и качество держится. На карточке видно цену против оценки и разрыв между ними.</p><p class="partners-format__limit">Дисконт — это отправной вопрос. Часто цена так выглядит потому, что рынок закладывает проблему, которую модель не увидела.</p></div><div class="partners-format"><span>Еженедельно · в Partner Cabinet</span><strong>🏛 Качество, за которым идут деньги</strong><p>Хорошее качество бизнеса там, где те, кто обязан декларировать сделки, — инсайдеры, отслеживаемые фонды или и те и другие — добирали позицию. Карточка показывает обе стороны и то, во что они добирают.</p><p class="partners-format__limit">Состав держателей — слой подтверждения, а не тезис. Те, кто подаёт отчётность, ошибаются со временем входа не реже, чем угадывают.</p></div></div></div><h3 id="держатели-и-денежныи-поток" tabindex="-1">Держатели и денежный поток <a class="header-anchor" href="#держатели-и-денежныи-поток" aria-label="Permalink to &quot;Держатели и денежный поток&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Еженедельно · в Partner Cabinet</span><strong>👤 Инсайдеры покупают</strong><p>Заметные чистые покупки на открытом рынке за последние месяцы — от людей, декларирующих каждую сделку. Карточка показывает обе стороны в валовых числах, а не только нетто, и согласны ли с этим фонды.</p><p class="partners-format__limit">Инсайдеры покупают по разным причинам и часто входят рано.</p></div><div class="partners-format"><span>Еженедельно · только в канале</span><strong>👤 Инсайдеры продают</strong><p>Тот же скрин с обратным знаком. Та же карточка, те же доказательства, противоположное направление.</p><p class="partners-format__limit">Продажи — рутина: диверсификация и налоги в отчётности выглядят так же, как потеря веры в компанию.</p></div><div class="partners-format"><span>Еженедельно · только в канале</span><strong>💸 Денежный поток говорит другое</strong><p>Отчётная прибыль отрицательная или тонкая, а свободный денежный поток продолжает расти. На карточке F-Score Пиотроски вынесен в отдельную панель — именно он отделяет улучшение операций от компании, которая проедает саму себя.</p><p class="partners-format__limit">Растущий кэш может быть недооценкой, а может быть срезанными инвестициями. Показатель здесь — F-Score, а не заголовок.</p></div></div></div><h2 id="как-выглядят-карточки" tabindex="-1">Как выглядят карточки <a class="header-anchor" href="#как-выглядят-карточки" aria-label="Permalink to &quot;Как выглядят карточки&quot;">​</a></h2><p>Каждый формат рисует свою карточку из собственных цифр компании.</p>',23)),s("div",g,[s("div",h,[r(e,{src:"/partners/examples/idea-turnaround-sample.png",alt:"Карточка идеи TickerForge «Разворот»: шкала оценки разворота, состав оценки по блокам и качество бизнеса под ней",caption:"Разворот — оценка и блоки, из которых она сложилась.","zoom-label":"Открыть карточку в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),r(e,{src:"/partners/examples/idea-triple-rated-sample.png",alt:"Карточка идеи TickerForge «Тройной рейтинг»: три порога качества, у каждого отмечено своё пороговое значение",caption:"Тройной рейтинг — каждый порог с отметкой на шкале.","zoom-label":"Открыть карточку в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),r(e,{src:"/partners/examples/idea-gems-growth-sample.png",alt:"Карточка идеи TickerForge «Рост в цифрах»: выручка, прибыль и денежный поток столбиками по обе стороны от нуля",caption:"Рост — три линии, каждая окрашена по своему направлению.","zoom-label":"Открыть карточку в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),r(e,{src:"/partners/examples/idea-gems-value-sample.png",alt:"Карточка идеи TickerForge «Дешевле своей стоимости»: цена против оценки справедливой стоимости и разрыв между ними",caption:"Недооценка — цена, оценка и разрыв.","zoom-label":"Открыть карточку в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),r(e,{src:"/partners/examples/idea-gems-ownership-sample.png",alt:"Карточка идеи TickerForge «Качество, за которым идут деньги»: активность фондов и инсайдеров над качеством бизнеса",caption:"Держатели — обе стороны и то, что они поддерживают.","zoom-label":"Открыть карточку в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),r(e,{src:"/partners/examples/idea-insider-buying-sample.png",alt:"Карточка идеи TickerForge «Инсайдеры покупают»: валовые покупки и продажи, рядом сторона фондов",caption:"Инсайдеры покупают — валовые числа, а не только нетто.","zoom-label":"Открыть карточку в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),a[1]||(a[1]=n('<h2 id="зачем-каналу-это-публиковать" tabindex="-1">Зачем каналу это публиковать <a class="header-anchor" href="#зачем-каналу-это-публиковать" aria-label="Permalink to &quot;Зачем каналу это публиковать&quot;">​</a></h2><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>Ритм</span><strong>Тему выбирает скрин.</strong><p>Регулярный формат означает, что публиковать по расписанию есть что и без поиска темы, а читатели привыкают этого ждать.</p></div><div class="partners-card"><span>Доверие</span><strong>Доказательства под вашим собственным выводом.</strong><p>Голос и точка зрения остаются вашими. Карточка подкладывает под них цифры, а напечатанные ограничения — то, что не даёт исследовательскому посту читаться как наводка.</p></div><div class="partners-card"><span>Измеримость</span><strong>В каждом посте отслеживаемая ссылка.</strong><p>Клики, запуски бота и привязка рефералов видны в Partner Cabinet — формат, который не работает, можно отключить по фактам, а не по ощущению.</p></div></div><p>Шесть из девяти генерируются в Partner Cabinet в одно нажатие. Три помеченных «только в канале» публикует TickerForge, но не под именем партнёра: два из них — негативные показания, а публиковать «у этой компании проблемы» под своей подписью — другой редакционный поступок, чем публиковать идею.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/ru/partners/stock-analysis-and-ideas">Посмотреть партнёрские форматы</a><a class="partners-button partners-button--secondary" href="/ru/market-intelligence/">Чтения рынка, а не идеи по компаниям</a></div>',4)),r(i,{locale:"ru"}),a[2]||(a[2]=s("h2",{id:"pilot",tabindex:"-1"},[c("Публиковать это в своём канале "),s("a",{class:"header-anchor",href:"#pilot","aria-label":'Permalink to "Публиковать это в своём канале {#pilot}"'},"​")],-1)),a[3]||(a[3]=s("p",null,"Каждый формат выше генерируется с вашей отслеживаемой ссылкой внутри, в одно нажатие, из Partner Cabinet. Расскажите, где вы публикуете и какие форматы ваша аудитория действительно стала бы читать.",-1)),s("div",v,[r(o,{source:"stock_ideas",locale:"ru",defaultProgram:"TELEGRAM_RESEARCH"})]),a[4]||(a[4]=n('<h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/partners/stock-analysis-and-ideas">Партнёрство: анализ акций и идеи</a> — что входит в пилот и как считается результат.</li><li><a href="/ru/market-intelligence/">Market Intelligence</a> — пять регулярных чтений состояния рынка, а не отдельных компаний.</li><li><a href="/stockdiscovery">Stock Discovery</a> — прогнать те же скрины самому, по тому же срезу.</li><li><a href="/methodology/tickerforge-score">TickerForge Score</a> и <a href="/methodology/risk-score">Risk Score</a> — как устроены показания за этими порогами (на английском).</li></ul>',2))])}const x=l(m,[["render",_]]);export{C as __pageData,x as default};
